CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE users(user_id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('ADMIN','AUTHOR','REVIEWER')),department VARCHAR(100),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE venues(venue_id SERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,type VARCHAR(20) NOT NULL CHECK(type IN('CONFERENCE','JOURNAL','WORKSHOP')),submission_deadline DATE,review_deadline DATE,CHECK(review_deadline IS NULL OR submission_deadline IS NULL OR review_deadline>=submission_deadline));
CREATE TABLE papers(paper_id SERIAL PRIMARY KEY,title VARCHAR(300) NOT NULL,abstract TEXT NOT NULL CHECK(length(abstract)>=40),status VARCHAR(20) NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN('SUBMITTED','UNDER_REVIEW','ACCEPTED','REJECTED','WITHDRAWN')),primary_author_id INT NOT NULL REFERENCES users(user_id),venue_id INT REFERENCES venues(venue_id),plagiarism_score NUMERIC(5,2) CHECK(plagiarism_score BETWEEN 0 AND 100),submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,search_vector tsvector GENERATED ALWAYS AS(to_tsvector('english',title||' '||abstract)) STORED);
CREATE TABLE paper_authors(paper_id INT REFERENCES papers(paper_id) ON DELETE CASCADE,user_id INT REFERENCES users(user_id) ON DELETE CASCADE,author_order SMALLINT NOT NULL CHECK(author_order>0),PRIMARY KEY(paper_id,user_id),UNIQUE(paper_id,author_order));CREATE TABLE keywords(keyword_id SERIAL PRIMARY KEY,keyword_text VARCHAR(80) UNIQUE NOT NULL);CREATE TABLE paper_keywords(paper_id INT REFERENCES papers(paper_id) ON DELETE CASCADE,keyword_id INT REFERENCES keywords(keyword_id) ON DELETE CASCADE,PRIMARY KEY(paper_id,keyword_id));
CREATE TABLE review_assignments(assignment_id SERIAL PRIMARY KEY,paper_id INT NOT NULL REFERENCES papers(paper_id) ON DELETE CASCADE,reviewer_id INT NOT NULL REFERENCES users(user_id),assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','COMPLETED','DECLINED')),UNIQUE(paper_id,reviewer_id));CREATE TABLE reviews(review_id SERIAL PRIMARY KEY,assignment_id INT UNIQUE NOT NULL REFERENCES review_assignments(assignment_id) ON DELETE CASCADE,score SMALLINT NOT NULL CHECK(score BETWEEN 1 AND 10),recommendation VARCHAR(20) NOT NULL CHECK(recommendation IN('ACCEPT','MINOR_REVISION','MAJOR_REVISION','REJECT')),comments TEXT,reviewed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE notifications(notification_id SERIAL PRIMARY KEY,user_id INT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,message VARCHAR(300) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE audit_log(log_id SERIAL PRIMARY KEY,paper_id INT NOT NULL REFERENCES papers(paper_id) ON DELETE CASCADE,old_status VARCHAR(20),new_status VARCHAR(20) NOT NULL,changed_by INT REFERENCES users(user_id),changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE paper_embeddings(paper_id INT PRIMARY KEY REFERENCES papers(paper_id) ON DELETE CASCADE,embedding vector(384) NOT NULL,model_name VARCHAR(60) NOT NULL DEFAULT 'all-MiniLM-L6-v2');
CREATE INDEX idx_papers_fts ON papers USING GIN(search_vector);CREATE INDEX idx_embeddings_ivf ON paper_embeddings USING ivfflat(embedding vector_cosine_ops) WITH(lists=100);
CREATE VIEW reviewer_workload AS SELECT u.user_id,u.name,COUNT(*) FILTER(WHERE ra.status='PENDING') active_assignments FROM users u JOIN review_assignments ra ON ra.reviewer_id=u.user_id WHERE u.role='REVIEWER' GROUP BY u.user_id,u.name;
CREATE OR REPLACE FUNCTION avg_review_score(pid INT) RETURNS NUMERIC LANGUAGE sql AS $$SELECT COALESCE(AVG(r.score),0) FROM reviews r JOIN review_assignments a ON a.assignment_id=r.assignment_id WHERE a.paper_id=pid$$;
CREATE OR REPLACE FUNCTION fn_status_audit() RETURNS TRIGGER LANGUAGE plpgsql AS $$BEGIN IF OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO audit_log(paper_id,old_status,new_status,changed_by) VALUES(NEW.paper_id,OLD.status,NEW.status,NEW.primary_author_id);END IF;RETURN NEW;END$$;CREATE TRIGGER trg_status_audit AFTER UPDATE OF status ON papers FOR EACH ROW EXECUTE FUNCTION fn_status_audit();
